(() => {
  const admins = [
    {name:"James Morrison",role:"Portal Administrator"},
    {name:"Sarah Jenkins",role:"Operations Administrator"},
    {name:"Mike Chen",role:"Support Administrator"},
    {name:"Larry Freeman Jr.",role:"HR Administrator"},
    {name:"System Admin",role:"System Administrator"},
  ];
  const assignableUsers = {
    "Administrator": admins,
    "Employee": [
      {name:"Marcus Johnson",role:"Security Officer"},
      {name:"Sarah Chen",role:"Patrol Supervisor"},
      {name:"Derek Wilson",role:"Mobile Patrol"},
      {name:"Priya Patel",role:"Site Inspector"},
      {name:"Mike Torres",role:"Response Guard"},
    ],
  };
  const state={screen:"helpdesk",tab:"unassigned",search:"",selected:null,tickets:[
    {id:"HD-1024",requester:"John Doe",requesterType:"Client",contact:"john.doe@client.com",category:"Reports",subject:"Unable to access site report",description:"The completed site report does not open from the client portal.",priority:"High",status:"Open",assignedTo:"Unassigned",site:"Downtown Financial Center",created:"Aug 5, 2026 09:20",lastActivity:"12 min ago",messages:[{by:"John Doe",at:"Aug 5, 9:20 AM",text:"Please help us access the submitted site report."}]},
    {id:"HD-1025",requester:"Sarah Jenkins",requesterType:"Admin",contact:"sarah@alexios.com",category:"Access",subject:"Account permission question",description:"Need confirmation of account permission scope.",priority:"Normal",status:"In Progress",assignedTo:"Mike Chen",site:"All Sites",created:"Aug 5, 2026 08:40",lastActivity:"26 min ago",messages:[]},
    {id:"HD-1026",requester:"Marcus Johnson",requesterType:"Employee",contact:"marcus@alexios.com",category:"Scheduling",subject:"Schedule swap error",description:"The approved shift swap is not showing in my schedule.",priority:"Normal",status:"Open",assignedTo:"James Morrison",site:"Westfield Mall",created:"Aug 4, 2026 14:15",lastActivity:"2 hrs ago",messages:[]},
    {id:"HD-1027",requester:"Derek Wilson",requesterType:"Employee",contact:"derek@alexios.com",category:"Payroll",subject:"Missing pay code in payroll",description:"Night shift premium is missing from the payroll review.",priority:"High",status:"Pending",assignedTo:"James Morrison",site:"Harbor District",created:"Aug 4, 2026 11:30",lastActivity:"1 day ago",messages:[]},
    {id:"HD-1028",requester:"Alice Smith",requesterType:"Client",contact:"alice@client.com",category:"Mobile App",subject:"Device not syncing checkpoints",description:"Checkpoint activity has stopped syncing from the assigned device.",priority:"Critical",status:"Open",assignedTo:"Unassigned",site:"Airport Terminal C",created:"Aug 3, 2026 16:45",lastActivity:"10 min ago",messages:[]}
  ]};
  const esc=s=>String(s??"").replace(/[&<>\"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
  const badge=v=>`<span class="hdu-badge ${String(v).toLowerCase().replace(/\s/g,'-')}">${esc(v)}</span>`;
  const btn=(label,act,kind="")=>`<button class="hdu-btn ${kind}" data-hdu="${act}">${label}</button>`;
  const now=()=>new Date().toLocaleString([], {month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'});
  function shell(content){return `<div class="hdu-shell"><main>${content}</main></div>`}
  function header(title,sub,actions=""){return `<header class="hdu-head"><div><h1>${title}</h1><p>${sub}</p></div><div>${actions}</div></header>`}
  function getHelp(){return header("Get Help","Find resources or raise a trackable support ticket.")+`<section class="hdu-help-grid"><article><i>?</i><h2>Resource Center</h2><p>Access product guides, operational references, and supporting information.</p>${btn("Open Resource Center","resource")}</article><article class="featured"><i>＋</i><h2>Raise Support Ticket</h2><p>Create a request on behalf of a client, administrator, or employee and track communication through Help Desk.</p>${btn("Create Ticket","new-ticket","primary")}</article></section>`}
  function filtered(){return state.tickets.filter(t=>{const tab=state.tab==='all'||(state.tab==='unassigned'&&t.assignedTo==='Unassigned')||(state.tab==='mine'&&t.assignedTo==='James Morrison');const q=state.search.toLowerCase();return tab&&(!q||[t.id,t.requester,t.subject,t.category,t.site].some(v=>v.toLowerCase().includes(q)))})}
  function helpDesk(){const rows=filtered();return header("Help Desk","Manage support requests raised by clients, administrators, and employees.",btn("+ New Ticket","new-ticket","primary"))+`<div class="hdu-tabs"><button data-tab="unassigned" class="${state.tab==='unassigned'?'active':''}">Unassigned <b>${state.tickets.filter(t=>t.assignedTo==='Unassigned').length}</b></button><button data-tab="mine" class="${state.tab==='mine'?'active':''}">Assigned to Me <b>${state.tickets.filter(t=>t.assignedTo==='James Morrison').length}</b></button><button data-tab="all" class="${state.tab==='all'?'active':''}">All <b>${state.tickets.length}</b></button></div><section class="hdu-panel"><div class="hdu-toolbar"><input data-search placeholder="Search by ID, requester, subject, category or site..." value="${esc(state.search)}"><select><option>All Statuses</option><option>Open</option><option>In Progress</option><option>Pending</option><option>Resolved</option></select></div><div class="hdu-table"><table><thead><tr><th>Ticket</th><th>Requester</th><th>Type</th><th>Category / Subject</th><th>Priority</th><th>Status</th><th>Assigned To</th><th>Created</th><th>Last Activity</th><th>Actions</th></tr></thead><tbody>${rows.length?rows.map(t=>`<tr data-id="${t.id}"><td><button class="hdu-link" data-hdu="view-ticket">${t.id}</button></td><td><b>${esc(t.requester)}</b><small>${esc(t.contact)}</small></td><td>${badge(t.requesterType)}</td><td><small>${esc(t.category)} · ${esc(t.site)}</small><b>${esc(t.subject)}</b></td><td>${badge(t.priority)}</td><td>${badge(t.status)}</td><td>${t.assignedTo==='Unassigned'?`<button class="hdu-unassigned" data-hdu="assign">Unassigned ▾</button>`:`<button class="hdu-assigned" data-hdu="assign">${esc(t.assignedTo)} ▾</button>`}</td><td>${t.created}</td><td>${t.lastActivity}</td><td><div class="hdu-row-actions"><button data-hdu="edit-ticket">Edit</button><button class="danger" data-hdu="delete-ticket">Delete</button></div></td></tr>`).join(''):`<tr><td colspan="10" class="hdu-empty">No tickets match this view.</td></tr>`}</tbody></table></div></section>`}
  function ticketForm(ticket){const t=ticket||{requesterType:'Client',priority:'Normal',status:'Open',assignedTo:'Unassigned',site:'All Sites'};return `<div class="hdu-overlay"><div class="hdu-dialog"><header><div><h2>${ticket?'Edit Ticket':'Raise Support Ticket'}</h2><p>${ticket?ticket.id:'Create a request for a client, administrator, or employee.'}</p></div><button data-hdu="close">×</button></header><div class="hdu-grid"><label>Requester Type<select data-f="requesterType"><option ${t.requesterType==='Client'?'selected':''}>Client</option><option ${t.requesterType==='Admin'?'selected':''}>Admin</option><option ${t.requesterType==='Employee'?'selected':''}>Employee</option></select></label><label>Requester Name<input data-f="requester" value="${esc(t.requester||'')}"></label><label>Contact Email / Phone<input data-f="contact" value="${esc(t.contact||'')}"></label><label>Category<select data-f="category">${['Access','Scheduling','Time Clock','Payroll','Reports','Mobile App','Billing','Other'].map(v=>`<option ${t.category===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Priority<select data-f="priority">${['Low','Normal','High','Critical'].map(v=>`<option ${t.priority===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Site / Client<input data-f="site" value="${esc(t.site||'')}"></label><label class="wide">Subject<input data-f="subject" value="${esc(t.subject||'')}"></label><label class="wide">Description<textarea data-f="description">${esc(t.description||'')}</textarea></label>${ticket?`<label>Status<select data-f="status">${['Open','In Progress','Pending','Resolved','Closed'].map(v=>`<option ${t.status===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Assigned To<select data-f="assignedTo"><option>Unassigned</option>${admins.map(a=>`<option ${t.assignedTo===a.name?'selected':''}>${a.name}</option>`).join('')}</select></label>`:''}</div><footer>${btn("Cancel","close")}${btn(ticket?'Save Changes':'Submit Ticket',ticket?'save-edit':'submit-ticket','primary')}</footer></div></div>`}
  function assignmentModal(ticket){const defaultType=assignableUsers.Employee.some(u=>u.name===ticket.assignedTo)?'Employee':'Administrator';return `<div class="hdu-overlay hdu-assignment" data-ticket="${ticket.id}"><div class="hdu-dialog compact"><header><div><h2>Assign Ticket</h2><p>${ticket.id} · ${esc(ticket.subject)}</p></div><button data-hdu="close">×</button></header><div class="hdu-grid one"><label>User Type<select data-assign-type><option ${defaultType==='Administrator'?'selected':''}>Administrator</option><option ${defaultType==='Employee'?'selected':''}>Employee</option></select></label><label>Select User<select data-assign-user>${assignableUsers[defaultType].map(u=>`<option value="${u.name}" ${ticket.assignedTo===u.name?'selected':''}>${u.name} — ${u.role}</option>`).join('')}</select></label><label class="hdu-unassign-check"><input type="checkbox" data-unassign> Return ticket to Unassigned queue</label></div><div class="hdu-assignment-summary"><span>Current assignment</span><b>${esc(ticket.assignedTo)}</b></div><footer>${btn("Cancel","close")}${btn("Assign Ticket","submit-assignment","primary")}</footer></div></div>`}
  function detail(t){return `<div class="hdu-overlay"><div class="hdu-dialog wide"><header><div><h2>${t.id} · ${esc(t.subject)}</h2><p>${t.requesterType}: ${esc(t.requester)} · ${esc(t.contact)}</p></div><button data-hdu="close">×</button></header><div class="hdu-summary"><div><span>Priority</span>${badge(t.priority)}</div><div><span>Status</span>${badge(t.status)}</div><div><span>Assigned To</span><b>${esc(t.assignedTo)}</b></div><div><span>Site</span><b>${esc(t.site)}</b></div></div><section class="hdu-description"><h3>Request Details</h3><p>${esc(t.description)}</p></section><section class="hdu-thread"><h3>Communication</h3>${t.messages.length?t.messages.map(m=>`<article><div><b>${esc(m.by)}</b><small>${m.at}</small></div><p>${esc(m.text)}</p></article>`).join(''):`<p class="muted">No communication has been added.</p>`}<label>Reply<textarea data-reply placeholder="Write a response or internal update..."></textarea></label></section><footer>${btn("Edit Ticket","edit-ticket")}${btn("Send Reply","send-reply","primary")}</footer></div></div>`}
  function render(){const host=document.getElementById('support-ui-fix');if(host)host.innerHTML=shell(state.screen==='gethelp'?getHelp():helpDesk())}
  function mount(screen){document.getElementById('payroll-ui-fix')?.remove();let host=document.getElementById('support-ui-fix');const app=document.querySelector('#root > div > div.flex.flex-col.flex-1')||document.querySelector('#root');if(!host&&app){host=document.createElement('div');host.id='support-ui-fix';app.style.position='relative';app.appendChild(host)}state.screen=screen;render()}
  const unmount=()=>document.getElementById('support-ui-fix')?.remove();
  document.addEventListener('click',e=>{
    const button=e.target.closest('button');if(!button)return;const text=button.textContent.replace(/\s+/g,' ').trim();
    if(['Get Help','Need Help','Help'].includes(text)){setTimeout(()=>mount('gethelp'),20);return}
    if(text==='Help Desk'){setTimeout(()=>mount('helpdesk'),20);return}
    if(!button.closest('#support-ui-fix')){if(button.closest('aside'))unmount();return}
    const host=button.closest('#support-ui-fix'),act=button.dataset.hdu,row=button.closest('tr'),ticket=row?state.tickets.find(t=>t.id===row.dataset.id):state.selected;
    if(button.dataset.tab){state.tab=button.dataset.tab;render();return}
    if(act==='new-ticket')host.insertAdjacentHTML('beforeend',ticketForm())
    else if(act==='edit-ticket'){state.selected=ticket;host.insertAdjacentHTML('beforeend',ticketForm(ticket))}
    else if(act==='delete-ticket'&&confirm(`Delete ${ticket.id}?`)){state.tickets=state.tickets.filter(t=>t.id!==ticket.id);render()}
    else if(act==='assign')host.insertAdjacentHTML('beforeend',assignmentModal(ticket))
    else if(act==='view-ticket'){state.selected=ticket;host.insertAdjacentHTML('beforeend',detail(ticket))}
    else if(act==='close')button.closest('.hdu-overlay')?.remove()
    else if(act==='submit-ticket'||act==='save-edit')saveTicket(button.closest('.hdu-overlay'),act==='save-edit')
    else if(act==='submit-assignment'){
      const box=button.closest('.hdu-assignment'),target=state.tickets.find(t=>t.id===box.dataset.ticket),unassigned=box.querySelector('[data-unassign]').checked,user=box.querySelector('[data-assign-user]').value;
      target.assignedTo=unassigned?'Unassigned':user;target.lastActivity='Just now';box.remove();render();
    }
    else if(act==='send-reply'){const box=button.closest('.hdu-overlay'),text=box.querySelector('[data-reply]').value.trim();if(text){state.selected.messages.push({by:'James Morrison',at:now(),text});state.selected.lastActivity='Just now';box.remove();host.insertAdjacentHTML('beforeend',detail(state.selected))}}
    else if(act==='resource'||act==='expert')alert(act==='resource'?'Resource Center selected.':'Expert contact selected. You may also raise a support ticket for tracked communication.')
  },true);
  let searchTimer;
  document.addEventListener('input',e=>{if(e.target.matches('#support-ui-fix [data-search]')){state.search=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{render();const input=document.querySelector('#support-ui-fix [data-search]');input?.focus();input?.setSelectionRange(state.search.length,state.search.length)},180)}},true);
  document.addEventListener('change',e=>{
    if(e.target.matches('.hdu-assignment [data-assign-type]')){
      const box=e.target.closest('.hdu-assignment'),users=assignableUsers[e.target.value],select=box.querySelector('[data-assign-user]');
      select.innerHTML=users.map(u=>`<option value="${u.name}">${u.name} — ${u.role}</option>`).join('');
      box.querySelector('[data-unassign]').checked=false;
    }
    if(e.target.matches('.hdu-assignment [data-unassign]'))boxToggleAssignment(e.target.closest('.hdu-assignment'),e.target.checked);
  },true);
  function boxToggleAssignment(box,disabled){box.querySelector('[data-assign-type]').disabled=disabled;box.querySelector('[data-assign-user]').disabled=disabled}
  function saveTicket(box,editing){const v=k=>box.querySelector(`[data-f="${k}"]`)?.value.trim()||'',required=['requester','contact','subject','description'];if(required.some(k=>!v(k))){alert('Requester, contact, subject and description are required.');return}if(editing){Object.assign(state.selected,{requesterType:v('requesterType'),requester:v('requester'),contact:v('contact'),category:v('category'),priority:v('priority'),site:v('site'),subject:v('subject'),description:v('description'),status:v('status'),assignedTo:v('assignedTo'),lastActivity:'Just now'})}else{const next=1030+state.tickets.length;state.tickets.unshift({id:`HD-${next}`,requesterType:v('requesterType'),requester:v('requester'),contact:v('contact'),category:v('category'),priority:v('priority'),site:v('site'),subject:v('subject'),description:v('description'),status:'Open',assignedTo:'Unassigned',created:now(),lastActivity:'Just now',messages:[{by:v('requester'),at:now(),text:v('description')}]});state.screen='helpdesk';state.tab='unassigned'}box.remove();render()}
})();
